    result = ''
    for char in message:
        if char.isupper():
            result += chr((ord(char) - 65 + 2) % 26 + 65)
        elif char.islower():
            result += chr((ord(char) - 97 + 2) % 26 + 97)
        elif char in vowels:
            if char.isupper():
                result += chr((ord(char) - 65 + 2) % 26 + 65)
            else:
                result += chr((ord(char) - 97 + 2) % 26 + 97)
        else:
            result += char
    return result
